import { useFormQuery } from "qortex-form-react/query";

const { Provider, save, isLoading, isSaving, isChanged } = useFormQuery({
  key: ["product", id],
  fetcher: () => api.getProduct(id),
  mutationFn: (draft) => api.updateProduct(id, draft),
  persist: { draft: true },
});

const { Provider, save, isSaving } = useFormQuery({
  key: ["product", "new"],
  initialData: { title: "", price: 0 },
  mutationFn: (draft) => api.createProduct(draft),
});

const { form, draft, set, save } = useForm({
  initialData: { theme: "system", emails: true },
});

await save(async (d) => {
  localStorage.setItem("settings", JSON.stringify(d));
});
